use std::{fs,collections::{BTreeMap,BTreeSet}};use serde_json::{json,Value};use zopro_bn254::Fr;use zopro_prover::zopro_core::artifact::Artifact;
#[global_allocator]static ALLOCATOR:zopro_prover::zopro_core::alloc::Allocator=zopro_prover::zopro_core::alloc::Allocator;
mod legacy;
type Word=[u64;4];
fn words(v:&Fr,canonical:bool)->Word{if canonical{v.to_canonical()}else{v.0}}
fn policy(v:&[Word])->Option<(usize,usize)>{use std::collections::HashSet;if !(256..u32::MAX as usize).contains(&v.len()){return None;}let size=v.len().min(2048);let stride=v.len().div_ceil(size);let unique:HashSet<&Word,ahash::RandomState>=v.iter().step_by(stride).take(size).collect();let observed=v.len().div_ceil(stride).min(size);if unique.len()*200>observed*199{return None;}let percent=if(32768..65536).contains(&v.len()){95}else{80};let zeros=v.iter().step_by(stride).take(size).filter(|s|**s==[0;4]).count();let nonzero=observed-zeros;if unique.len()-usize::from(zeros!=0)==nonzero&&nonzero*100>observed*percent{return None;}Some(((unique.len()*16).min(v.len()*percent/100).min(32768),percent))}
fn shared(frame:&[Word],queries:[&[u32];2],percent:[usize;2])->([Option<legacy::Groups>;2],usize,usize){let mut representatives=BTreeMap::<Word,u32>::new();let mut labels=vec![u32::MAX;frame.len()];let union:BTreeSet<_>=queries.into_iter().flat_map(|q|q.iter().copied()).collect();let mut visits=0;for &wire in &union{let v=frame[wire as usize];if v==[0;4]{continue;}visits+=1;let rep=*representatives.entry(v).or_insert(wire);labels[wire as usize]=rep;}
let groups=std::array::from_fn(|query|{let ids=queries[query];let mut local=vec![u32::MAX;frame.len()];let mut result=legacy::Groups{len:ids.len(),values:vec![],order:vec![],starts:vec![0],counts:vec![]};let mut members=Vec::<Vec<u32>>::new();for(i,&wire)in ids.iter().enumerate(){let rep=labels[wire as usize];if rep==u32::MAX{continue;}let c=&mut local[rep as usize];if *c==u32::MAX{*c=result.values.len()as u32;result.values.push(frame[wire as usize]);result.counts.push(0);members.push(vec![]);}let c=*c as usize;result.counts[c]+=1;members[c].push(i as u32);}if result.values.len()*100>ids.len()*percent[query]{return None;}for m in members{result.order.extend(m);result.starts.push(result.order.len());}Some(result)});(groups,visits,representatives.len())}
fn metadata_model(n:usize,a:usize,b:usize)->Value{let buckets=|n:usize|n.checked_mul(8).unwrap().div_ceil(7).checked_next_power_of_two().unwrap().max(4);let old=buckets(a).checked_mul(41).unwrap()+buckets(a)/2*41+160+buckets(b)*41+buckets(b)/2*41+160;let new=n.checked_mul(12).unwrap();json!({"dense_labels_and_two_local_remaps_bytes":new,"old_conservative_two_map_bytes":old,"dense_metadata_fits_old_map_bound":new<=old,"not_complete_total_forecast":true})}
fn main(){let cases:Value=serde_json::from_slice(&fs::read(std::env::args().nth(1).unwrap()).unwrap()).unwrap();let pool=rayon::ThreadPoolBuilder::new().num_threads(32).build().unwrap();pool.install(||{for case in cases.as_array().unwrap().iter().take(9){let bytes=fs::read(case["key"].as_str().unwrap()).unwrap();let request=fs::read_to_string(case["request"].as_str().unwrap()).unwrap();let sdk=zopro_zolana::Prover::load(&bytes).unwrap();let witness=sdk.witness(&request).unwrap();let image=sdk.solver_image().unwrap();drop(sdk);let u32at=|i:usize|u32::from_le_bytes(image[4*i..4*i+4].try_into().unwrap())as usize;assert_eq!(u32at(0),0x3150535a);assert_eq!(u32at(1),zopro_prover::zopro_core::solver_image_version()as usize);let(nwire,npublic,na,nb)=(u32at(2),u32at(4),u32at(6),u32at(7));assert!(52+4*(na+nb)<=image.len());let ai=(0..na).map(|i|u32at(13+i)as u32).collect::<Vec<_>>();let bi=(0..nb).map(|i|u32at(13+na+i)as u32).collect::<Vec<_>>();for q in[&ai,&bi]{assert!(q.windows(2).all(|p|p[0]<p[1]));assert!(q.iter().all(|&v|(v as usize)<nwire));}
let artifact=Artifact::parse(&bytes).unwrap();let key=artifact.key(artifact.points(),Some(&image)).unwrap();let raw=artifact.key(artifact.points(),None).unwrap();let wbytes:Vec<_>=witness.iter().flat_map(|v|v.0.iter().flat_map(|v|v.to_le_bytes())).collect();let values=key.msm_scalars(&wbytes).unwrap();let raw_values=raw.msm_scalars(&wbytes).unwrap();assert_eq!(values,raw_values);drop(raw);drop(key);assert_eq!(values[0].len(),na);assert_eq!(values[1].len(),nb);assert_eq!(values[2].len(),nwire-npublic);let canonical=values.iter().map(Vec::len).max().unwrap()<65536;
let mut frame=Vec::with_capacity(nwire);frame.push(words(&Fr::ONE,canonical));for i in 1..npublic{frame.push(words(&Fr::from_montgomery(witness[i-1].0),canonical));}frame.extend(values[2].iter().map(|v|words(v,canonical)));assert_eq!(frame.len(),nwire);let queries=[values[0].iter().map(|v|words(v,canonical)).collect::<Vec<_>>(),values[1].iter().map(|v|words(v,canonical)).collect::<Vec<_>>()];for (q,ids)in queries.iter().zip([&ai,&bi]){for(&v,&id)in q.iter().zip(ids){assert_eq!(v,frame[id as usize]);}}
let policies=[policy(&queries[0]),policy(&queries[1])];let empty=vec![];let active=[if policies[0].is_some(){&ai[..]}else{&empty[..]},if policies[1].is_some(){&bi[..]}else{&empty[..]}];let percent=std::array::from_fn(|q|policies[q].map(|p|p.1).unwrap_or(80));let(mut g,global_visits,classes)=shared(&frame,active,percent);for q in 0..2{if policies[q].is_none(){g[q]=None;}}let original=std::array::from_fn::<_,2,_>(|q|policies[q].and_then(|(cap,p)|legacy::original(&queries[q],cap,p,ahash::RandomState::with_seeds(1,2,3,4))));assert_eq!(g,original);let separate_visits=(0..2).filter(|&q|policies[q].is_some()).map(|q|queries[q].iter().filter(|&&v|v!=[0;4]).count()).sum::<usize>();let union=ai.iter().chain(&bi).copied().collect::<BTreeSet<_>>().len();let metadata=metadata_model(nwire,na,nb);println!("ROW {}",json!({"shape":case["shape"],"n_wires":nwire,"A_indices":na,"B_indices":nb,"union_wires":union,"overlapping_wires":na+nb-union,"separate_nonzero_hash_visits":separate_visits,"shared_nonzero_hash_visits":global_visits,"hash_visit_saving_fraction":1.-global_visits as f64/separate_visits.max(1)as f64,"global_nonzero_scalar_classes":classes,"query_sample_admits":[policies[0].is_some(),policies[1].is_some()],"query_grouping_admits":[g[0].is_some(),g[1].is_some()],"exact_metadata_equal":true,"query_scalars_equal_wire_values":true,"raw_cached_solution_equal":true,"metadata":metadata,"representation":if canonical{"canonical"}else{"Montgomery"}}));}});println!("COMPLETE ninefixtures,18queryconstructors_exact,18raw_cached_solves,noSDKproofs,no_array_exports");}
#[cfg(test)]mod tests{use super::*;#[test]fn overlapping_disjoint_empty_zero_and_fullword_cases(){for n in[0usize,1,7,256,1025]{for pattern in 0..5{let frame:Vec<_>=(0..n).map(|i|match pattern{0=>[0;4],1=>[7,8,9,10],2=>[(i%17)as u64,4,3,2],3=>[i as u64,4,3,!i as u64],_=>if i%5==0{[0;4]}else{[i as u64*1597,i as u64*65537,!i as u64,7]}}).collect();for geometry in 0..3{let ai=(0..n).filter(|i|geometry==0||i%2==0).map(|i|i as u32).collect::<Vec<_>>();let bi=(0..n).filter(|i|geometry==0||geometry==1&&i%2!=0).map(|i|i as u32).collect::<Vec<_>>();let(g,_,_)=shared(&frame,[&ai,&bi],[80,80]);for(q,ids)in[ai,bi].iter().enumerate(){let values=ids.iter().map(|&i|frame[i as usize]).collect::<Vec<_>>();assert_eq!(g[q],legacy::original(&values,0,80,ahash::RandomState::with_seeds(1,2,3,4)));}}}}}}
